DARK_TEXT = {"#FCC624", "#F2CC0C", "#FF9900", "#F38020"}

def write(name, w, h, body, css=""):
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">
<defs>{GRAD}<linearGradient id="gl" gradientUnits="userSpaceOnUse" x1="0" x2="{w}" y1="0" y2="0"><stop offset="0" stop-color="#00ADD8"/><stop offset=".5" stop-color="#7B42BC"/><stop offset="1" stop-color="#E6522C"/></linearGradient></defs>
<style>{css}</style>
<rect x=".5" y=".5" width="{w-1}" height="{h-1}" rx="14" fill="{BG}" stroke="{BORDER}"/>
{body}
</svg>'''
    open(os.path.join(OUT, name), "w").write(svg)

# ---------- header ----------
pts = [8,9,8,10,9,8,9,8,10,9,8,9,8,10,9,8,9,8,9,22,10,9,8,9,8,9,10,8,9,8]
step = 1000/(len(pts)-1)
path = "M" + " L".join(f"{i*step:.1f},{250-p*2.2:.1f}" for i,p in enumerate(pts))
grid = "".join(f'<line x1="{x}" y1="0" x2="{x}" y2="280" stroke="#161b22"/>' for x in range(0,1000,40)) + \
       "".join(f'<line x1="0" y1="{y}" x2="1000" y2="{y}" stroke="#161b22"/>' for y in range(0,280,40))
write("header.svg", 1000, 280, f'''
<clipPath id="c"><rect width="1000" height="280" rx="14"/></clipPath><g clip-path="url(#c)">{grid}</g>
<text x="60" y="118" font-family="{SANS}" font-size="78" font-weight="800" fill="url(#g)" class="fade">stella</text>
<text x="64" y="160" font-family="{MONO}" font-size="20" fill="{FG}" class="fade d1">site reliability engineering</text>
<text x="64" y="190" font-family="{MONO}" font-size="14" fill="{MUTED}" class="fade d2">sicuani, cusco · perú</text>
<g transform="translate(700,62)" class="fade d2">
  <rect width="240" height="34" rx="17" fill="#0f2a1a" stroke="#238636"/>
  <circle cx="20" cy="17" r="5" fill="#3fb950" class="pulse"/>
  <text x="34" y="22" font-family="{MONO}" font-size="13" fill="#3fb950">all systems operational</text>
</g>
<g transform="translate(704,116)" font-family="{MONO}" font-size="13" class="fade d3">
  <text fill="{MUTED}">uptime<tspan x="80" fill="{FG}">99.95%</tspan></text>
  <text y="22" fill="{MUTED}">p99<tspan x="80" fill="{FG}">120ms</tspan></text>
  <text y="44" fill="{MUTED}">budget<tspan x="80" fill="{FG}">72% left</tspan></text>
</g>
<path d="{path}" fill="none" stroke="url(#gl)" stroke-width="2.5" stroke-linejoin="round" class="draw"/>
''', css='''
.fade{animation:fade .8s ease backwards}.d1{animation-delay:.3s}.d2{animation-delay:.6s}.d3{animation-delay:.9s}
@keyframes fade{from{opacity:0}}
.pulse{animation:pulse 1.6s ease-in-out infinite}@keyframes pulse{50%{opacity:.25}}
.draw{stroke-dasharray:1400;animation:draw 3s ease backwards .4s}@keyframes draw{from{stroke-dashoffset:1400}}
''')

# ---------- stack ----------
groups = [
  ("LANGUAGES",     [("Go","#00ADD8","go"),("Rust","#B7410E","rust"),("Python","#3776AB","python"),("Next.js","#2b2b2b","nextdotjs"),("TypeScript","#3178C6","typescript")]),
  ("CONTAINERS",    [("Docker","#2496ED","docker"),("Kubernetes","#326CE5","kubernetes"),("Helm","#0F1689","helm"),("Compose","#1D63ED","docker"),("Linux","#FCC624","linux")]),
  ("CLOUD &amp; IAC",   [("AWS","#FF9900","amazonwebservices"),("Google Cloud","#4285F4","googlecloud"),("Cloudflare","#F38020","cloudflare"),("Terraform","#7B42BC","terraform"),("GitHub Actions","#2088FF","githubactions")]),
  ("OBSERVABILITY", [("Prometheus","#E6522C","prometheus"),("Grafana","#F46800","grafana"),("Loki","#F2CC0C","grafana"),("OpenTelemetry","#425CC7","opentelemetry")]),
  ("DATA",          [("PostgreSQL","#4169E1","postgresql"),("Redis","#DC382D","redis"),("NATS","#27AAE1",None)]),
]
FS, CH, PAD, H, GAP = 14, 14*0.62, 16, 34, 10
body, y, n = "", 50, 0
for label, items in groups:
    body += f'<text x="40" y="{y+22}" font-family="{MONO}" font-size="12" letter-spacing="2" fill="{MUTED}">{label}</text>'
    x = 220
    for name, col, ic in items:
        IS = 16
        w = PAD + (IS + 8 if ic else 0) + len(name)*CH + PAD
        tc = "#0d1117" if col in DARK_TEXT else "#ffffff"
        icon = '' if ic is None else f'<path transform="translate({x+PAD:.1f},{y+(H-IS)/2:.1f}) scale({IS/24})" fill="{tc}" d="{ICONS[ic]}"/>'
        body += f'''<g class="pop" style="animation-delay:{n*0.06:.2f}s"><rect x="{x:.1f}" y="{y}" width="{w:.1f}" height="{H}" rx="8" fill="{col}"/>{icon}<text x="{x+PAD+(IS+8 if ic else 0):.1f}" y="{y+22}" font-family="{MONO}" font-size="{FS}" font-weight="700" fill="{tc}">{name}</text></g>'''
        x += w + GAP; n += 1
    y += H + 22
write("stack.svg", 1000, y+28, body, css=".pop{animation:pop .45s ease backwards}@keyframes pop{from{opacity:0;transform:translateY(6px)}}")

