xs = [135 + i*182 for i in range(5)]; cy = 105
body = f'<text x="500" y="40" text-anchor="middle" font-family="{MONO}" font-size="12" letter-spacing="3" fill="{MUTED}">HOW I WORK</text>'
track = f"M{xs[0]},{cy} L{xs[-1]},{cy} C{xs[-1]+110},{cy} {xs[-1]+110},{cy+135} {xs[-1]-60},{cy+135} L{xs[0]+60},{cy+135} C{xs[0]-110},{cy+135} {xs[0]-110},{cy} {xs[0]},{cy}"
body += f'<path id="t" d="{track}" fill="none" stroke="{BORDER}" stroke-width="2" stroke-dasharray="4 6"/>'
body += f'<path d="M{xs[0]},{cy} L{xs[-1]},{cy}" stroke="url(#gl)" stroke-width="2.5"/>'
for i,(name,sub,col) in enumerate(steps):
    x = xs[i]
    body += f'<circle cx="{x}" cy="{cy}" r="26" fill="{BG}" stroke="{col}" stroke-width="2.5"/>'
    body += f'<text x="{x}" y="{cy+5}" text-anchor="middle" font-family="{MONO}" font-size="14" font-weight="700" fill="{col}">0{i+1}</text>'
    body += f'<text x="{x}" y="{cy+52}" text-anchor="middle" font-family="{SANS}" font-size="17" font-weight="700" fill="{FG}">{name}</text>'
    body += f'<text x="{x}" y="{cy+72}" text-anchor="middle" font-family="{MONO}" font-size="11.5" fill="{MUTED}">{sub}</text>'
body += f'<circle r="5" fill="#3fb950"><animateMotion dur="7s" repeatCount="indefinite"><mpath href="#t"/></animateMotion></circle>'
body += f'<circle r="9" fill="#3fb950" opacity=".25"><animateMotion dur="7s" repeatCount="indefinite"><mpath href="#t"/></animateMotion></circle>'
write("sre-loop.svg", W, Hh, body)

# ---------- roadmap ----------
stages = [
  ("NOW",   "#3fb950", ["Go services", "Rust tooling"]),
  ("NEXT",  "#7B42BC", ["SLOs &amp; error budgets", "Kubernetes in prod", "Terraform + OTel"]),
  ("LATER", "#E6522C", ["chaos engineering", "on-call &amp; incidents"]),
]
body = f'<line x1="80" y1="70" x2="920" y2="70" stroke="{BORDER}" stroke-width="2"/><line x1="80" y1="70" x2="920" y2="70" stroke="url(#gl)" stroke-width="2" class="draw"/>'
for i,(lab,col,items) in enumerate(stages):
    cx = 80 + i*420
    anchor = ["start","middle","end"][i]
    body += f'<circle cx="{cx}" cy="70" r="9" fill="{BG}" stroke="{col}" stroke-width="3"/>'
    if i == 0: body += f'<circle cx="{cx}" cy="70" r="9" fill="none" stroke="{col}" stroke-width="2" class="ring"/>'
    body += f'<text x="{cx}" y="44" text-anchor="{anchor}" font-family="{MONO}" font-size="13" font-weight="700" letter-spacing="2" fill="{col}">{lab}</text>'
    for j,it in enumerate(items):
        body += f'<text x="{cx}" y="{106+j*22}" text-anchor="{anchor}" font-family="{MONO}" font-size="13.5" fill="{FG}">{it}</text>'
body += f'<text x="500" y="196" text-anchor="middle" font-family="{SANS}" font-size="13" font-style="italic" fill="{MUTED}">“hope is not a strategy.”</text>'
write("roadmap.svg", 1000, 220, body, css='''
.draw{stroke-dasharray:840;animation:draw 2.4s ease backwards}@keyframes draw{from{stroke-dashoffset:840}}
.ring{transform-box:fill-box;transform-origin:center;animation:ring 1.8s ease-out infinite}@keyframes ring{from{opacity:.9;transform:scale(1)}to{opacity:0;transform:scale(2.4)}}
''')
